    const cat = await getCatalog();
    const idx = cat.indexes.find((i) => i.name === indexName);
    if (!idx) {
      res.status(400).json({ error: `Unknown index: ${indexName}` });
      return;
    }
    if (!idx.evaluable) {
      res.status(400).json({
