    evalFile: path.relative(ROOT, evalFile),
    evalArtifact: evalBase,
    evalOutput: evalRes.stdout,
    retrievalCommand: searchRes.command,
    evaluationCommand: evalRes.command,
    retrievalMs: searchRes.durationMs,
