  --panel: #1e293b;
  --panel-2: #243149;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --accent: #38bdf8;
  --accent-2: #22d3ee;
  --good: #34d399;
  --bad: #f87171;
  --border: #334155;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.45;
}

header {
  padding: 1.5rem 2rem 1rem;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(180deg, #1e293b, #0f172a);
}

header h1 {
  margin: 0 0 0.25rem;
  font-size: 1.4rem;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  max-width: 60rem;
  font-size: 0.95rem;
}

.health {
  margin-top: 0.75rem;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  background: var(--panel-2);
  display: inline-block;
  font-size: 0.85rem;
  border: 1px solid var(--border);
}

.health.ok { border-color: var(--good); color: var(--good); }
.health.bad { border-color: var(--bad); color: var(--bad); }

main {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) minmax(280px, 1fr) minmax(320px, 1.4fr);
  gap: 1rem;
  padding: 1rem 2rem 2rem;
  align-items: start;
}

@media (max-width: 1100px) {
  main { grid-template-columns: 1fr; }
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
}

.panel h2 {
  margin-top: 0;
  font-size: 1.05rem;
}

.panel h3 {
  font-size: 0.95rem;
  margin: 1rem 0 0.5rem;
}

.panel-header {
  display:

