  $('#catalog-filter').addEventListener('input', (e) => {
    state.filter = e.target.value.toLowerCase();
    renderCatalogList();
  });
  $('#filter-evaluable').addEventListener('change', (e) => {
    state.evaluableOnly = e.target.checked;
    renderCatalogList();
  });
