  const msel = $('#metric-select');
  msel.innerHTML = '';
  // Prefer to show modern ranking metrics first when present.
  const preferred = ['nDCG@10', 'Recall@1000', 'R@1K'];
  const sorted = [...p.metrics].sort((a, b) => {
    const ai = preferred.indexOf(a.label);
