    return;
  }
  detail.innerHTML = '';
  const dl = el('dl', { dataset: { testid: 'index-detail' } });
  const rows = [
    ['Name', idx.name],
    ['Type', idx.type],
    ['Description', idx.description || '–'],
    ['Documents', idx.documents ? idx.documents.toLocaleString() : '–'],
