  const health = $('#health');
  try {
    const res = await fetch('/api/health');
    const data = await res.json();
    if (data.ok) {
      health.className = 'health ok';
      health.textContent = `✓ Java ${data.java.version}, Anserini jar: ${data.anseriniJar.jar.split('/').pop()}`;
