async function loadCatalog() {
  $('#catalog-list').innerHTML = '<li class="empty">Loading prebuilt-index registry (may take ~1 min on first load)…</li>';
  $('.catalog-stats').textContent = 'Loading…';
  try {
    const res = await fetch('/api/catalog');
