    $('#pairing-section').hidden = true;
  }
}

function renderPairing() {
  const idx = state.selectedIndex;
  if (!idx || !idx.evaluable) return;

  // Pairing select.
  const psel = $('#pairing-select');
  psel.innerHTML = '';
  idx.pairings.forEach((p, i) => {
