      },
      [
        el('div', { class: 'catalog-name' }, idx.name),
        el('div', { class: 'catalog-meta' }, [
          badge,
          el('span', {}, idx.type),
          idx.documents ? el('span', {}, `${idx.documents.toLocaleString()} docs`) : null,
          idx.size ? el('span', {}, fmtBytes(idx.size)) : null,
        ]),
      ]
    );
    ul.appendChild(item);
  }
