  state.selectedIndex = idx;
  state.selectedPairing = idx.pairings[0] || null;
  state.selectedMetric = state.selectedPairing?.metrics?.[0] || null;
  renderCatalogList();
  renderDetail();
  renderPairing();
}

function renderDetail() {
  const detail = $('#detail');
