      el('a', { href: `/api/artifacts/${data.runArtifact}`, target: '_blank' }, 'run file'),
      ' · ',
      el('a', { href: `/api/artifacts/${data.evalArtifact}`, target: '_blank' }, 'evaluation output'),
    ]
  ));
}

window.addEventListener('DOMContentLoaded', init);

