 *     a clear fallback to whatever metrics CACM does expose.
 *   - Clicking Run Evaluation produces a numeric score.
 *   - Run metadata (index, topics, metric, artifact paths) is shown.
 *   - At least one catalog-only or non-selected index is visible.
 *
 * The test fails if the app displays mocked catalog data or mocked evaluation
 * results: it verifies that the displayed retrieval/evaluation commands
 * reference the real Anserini fatjar and that the evaluator output contains
 * real `trec_eval`-style rows for the chosen metric.
 */

const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const path = require('node:path');

const ARTIFACTS_DIR = path.join(__dirname, '..', 'artifacts');

test('CACM end-to-end retrieval and evaluation through the browser', async ({ page }) => {
  // -------- Load the app --------
  await page.goto('/');
  await expect(page.locator('h1')).toHaveText(/Anserini Prebuilt Index Evaluator/);

  // Health check should be green (Java + fatjar resolved on the server).
  const health = page.getByTestId('health');
  await expect(health).toHaveClass(/ok/, { timeout: 30 * 1000 });

  // -------- Catalog should populate from the live registry --------
  const stats = page.getByTestId('catalog-stats');
  // Wait until catalog has been loaded (warmup + 1 JVM per config).
  await expect(stats).toContainText(/inverted indexes/i, { timeout: 120 * 1000 });
  const statsText = await stats.textContent();

  // Expect *many* indexes — not just one hardcoded CACM entry.
  const indexCount = Number((statsText.match(/(\d+)\s+inverted/) || [])[1]);
  expect(indexCount).toBeGreaterThan(10);

  const items = page.getByTestId('catalog-item');
  await expect(items.first()).toBeVisible();
  const itemCount = await items.count();
  expect(itemCount).toBeGreaterThan(10);

  // -------- Confirm CACM is selectable / selected --------
  // The app auto-selects CACM on load when present.
  const cacmItem = page.locator('[data-testid="catalog-item"][data-index-name="cacm"]');
  await expect(cacmItem).toBeVisible();
  await expect(cacmItem).toHaveClass(/selected/);
  await expect(cacmItem).toHaveAttribute('data-evaluable', 'true');

  // -------- Confirm at least one non-CACM and at least one catalog-only entry --------
  const otherEvaluable = page.locator(
    '[data-testid="catalog-item"][data-evaluable="true"]:not([data-index-name="cacm"])'
  );
  expect(await otherEvaluable.count()).toBeGreaterThan(0);

  const catalogOnly = page.locator('[data-testid="catalog-item"][data-evaluable="false"]');
  // We assert >= 1 catalog-only entry from the registry-derived catalog.
  expect(await catalogOnly.count()).toBeGreaterThanOrEqual(1);

  // -------- Confirm CACM shows a topic/qrels pairing --------
  await expect(page.locator('#pairing-section')).toBeVisible();
  const pairingSelect = page.getByTestId('pairing-select');
  await expect(pairingSelect).toBeVisible();
  // CACM has exactly one pairing in the shipped reproduce config (topics=cacm,
  // qrels=cacm). The displayed option should reflect that.
  const pairingText = await pairingSelect.locator('option').first().textContent();
  expect(pairingText).toMatch(/cacm/i);
  expect(pairingText).toMatch(/qrels:cacm/i);

  // -------- Pick a supported metric: prefer nDCG@10 or Recall@1000, fall back otherwise --------
  const metricSelect = page.getByTestId('metric-select');
  await expect(metricSelect).toBeVisible();
  const metricOptionTexts = await metricSelect.locator('option').allTextContents();
  expect(metricOptionTexts.length).toBeGreaterThan(0);
  let chosenMetric = null;
  for (const candidate of ['nDCG@10', 'Recall@1000']) {
    if (metricOptionTexts.some((t) => t.startsWith(candidate))) {
      chosenMetric = candidate;
      break;
    }
  }
  if (!chosenMetric) {
    // Clear fallback: just pick whatever the first option is.
    chosenMetric = (metricOptionTexts[0] || '').split(/\s+/)[0];
  }
  expect(chosenMetric).toBeTruthy();
  await metricSelect.selectOption(chosenMetric);

  // -------- Click Run Evaluation --------
  const runButton = page.getByTestId('run-button');
  await expect(runButton).toBeEnabled();
  const artifactsBefore = listArtifacts();
  await runButton.click();

  // The status pill should report progress.
  const status = page.getByTestId('run-status');
  await expect(status).toHaveClass(/running/, { timeout: 5 * 1000 });

  // CACM retrieval + eval finishes in seconds, but be generous on first run
  // since the prebuilt index may need to be downloaded.
  await expect(status).toHaveClass(/ok/, { timeout: 5 * 60 * 1000 });

  // -------- Verify a numeric score appears --------
  const scoreText = (await page.getByTestId('score-value').textContent()).trim();
  // Should parse as a finite number in [0, 1] for the metrics we expose.
  const scoreNum = Number(scoreText);
  expect(Number.isFinite(scoreNum)).toBe(true);
  expect(scoreNum).toBeGreaterThanOrEqual(0);
  expect(scoreNum).toBeLessThanOrEqual(1);
  await expect(page.getByTestId('score-label')).toHaveText(chosenMetric);

  // -------- Verify run metadata is displayed --------
  await expect(page.getByTestId('result-index')).toHaveText('cacm');
  await expect(page.getByTestId('result-topics')).toHaveText('cacm');
  await expect(page.getByTestId('result-qrels-eval-key')).toHaveText('cacm');
  await expect(page.getByTestId('result-metric')).toContainText(chosenMetric);
  await expect(page.getByTestId('result-run-file')).toContainText('artifacts/run.');
  await expect(page.getByTestId('result-evaluation-file')).toContainText('artifacts/eval.');

  // -------- Anti-mock checks: evaluator output and commands must look real --------
  const evalOutput = await page.getByTestId('eval-output').textContent();
  // trec_eval output for the "all" aggregate row should be present.
  expect(evalOutput).toMatch(/\tall\t\d+\.\d+/);

  const commands = await page.getByTestId('commands').textContent();
  expect(commands).toContain('io.anserini.search.SearchCollection');
  expect(commands).toContain('io.anserini.eval.TrecEval');
  expect(commands).toContain('anserini-');
  expect(commands).toContain('-fatjar.jar');

  const runPreview = await page.getByTestId('run-preview').textContent();
  // TREC run line: qid Q0 docid rank score tag
  expect(runPreview).toMatch(/\bQ0\b/);

  // -------- The server should have produced real artifact files on disk --------
  const artifactsAfter = listArtifacts();
  const newArtifacts = artifactsAfter.filter((a) => !artifactsBefore.includes(a));
  expect(newArtifacts.some((n) => n.startsWith('run.cacm.'))).toBe(true);
  expect(newArtifacts.some((n) => n.startsWith('eval.cacm.'))).toBe(true);
});

function listArtifacts() {
  if (!fs.existsSync(ARTIFACTS_DIR)) return [];
  return fs.readdirSync(ARTIFACTS_DIR);
}

{
  "name": "anserini-prebuilt-index-evaluator",
  "version": "0.1.0",
  "private": true,
  "description": "Local web app for browsing Anserini prebuilt Lucene inverted indexes and running reproducible retrieval evaluations.",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "test:e2e": "playwright test"
  },
  "dependencies": {
    "express": "^4.19.2",
    "yaml": "^2.5.0"
  },
  "devDependencies": {
    "@playwright/test": "^1.45.0"
  },
  "engines": {
    "node": ">=18"
  }
}

/**
 * Thin wrapper around the Anserini fatjar CLI.
 *
 * This module never mocks Anserini output. Every function in this file
 * shells out to `java -cp $ANSERINI_JAR <main-class>` and returns the
 * raw stdout/stderr so callers can verify they are using real Anserini.
 */

const { spawn } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const DEFAULT_JAR_DIR = path.join(__dirname, '..', 'anserini');

/**
 * Resolve the Anserini fatjar location.
 *
 * Order of resolution:
 *   1. ANSERINI_JAR env var, if set and points to an existing file.
 *   2. The single anserini-*-fatjar.jar file under ./anserini/.
 */
function resolveAnseriniJar() {
  const fromEnv = process.env.ANSERINI_JAR;
  if (fromEnv && fs.existsSync(fromEnv)) {
    return fromEnv;
  }
  if (fs.existsSync(DEFAULT_JAR_DIR)) {
    const matches = fs
      .readdirSync(DEFAULT_JAR_DIR)
      .filter((f) => /^anserini-.*-fatjar\.jar$/.test(f));
    if (matches.length > 0) {
      return path.join(DEFAULT_JAR_DIR, matches[0]);
    }
  }
  throw new Error(
    'Could not locate the Anserini fatjar. Set ANSERINI_JAR or place an ' +
      'anserini-*-fatjar.jar file under ./anserini/.'
  );
}

/**
 * Run a Java main class against the Anserini fatjar.
 *
 * @param {string} mainClass  Fully-qualified main class name.
 * @param {string[]} args     CLI args passed after the main class.
 * @param {object} [options]
 * @param {string} [options.cwd]      Working directory for the spawned process.
 * @param {number} [options.timeoutMs] Hard timeout in ms (default: 30 min).
 * @returns {Promise<{stdout: string, stderr: string, code: number, command: string, durationMs: number}>}
 */
function runJava(mainClass, args, options = {}) {
  const jar = resolveAnseriniJar();
  const cwd = options.cwd || process.cwd();
  const timeoutMs = options.timeoutMs || 30 * 60 * 1000;
  const fullArgs = ['-cp', jar, mainClass, ...args];
  const commandStr = `java -cp ${jar} ${mainClass} ${args.join(' ')}`;
  const start = Date.now();
  return new Promise((resolve, reject) => {
    const child = spawn('java', fullArgs, { cwd });
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(() => {
      child.kill('SIGKILL');
      reject(new Error(`Anserini command timed out after ${timeoutMs}ms: ${commandStr}`));
    }, timeoutMs);
    child.stdout.on('data', (d) => { stdout += d.toString(); });
    child.stderr.on('data', (d) => { stderr += d.toString(); });
    child.on('error', (err) => {
      clearTimeout(timer);
      reject(new Error(`Failed to spawn java: ${err.message}`));
    });
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({
        stdout,
        stderr,
        code: code == null ? -1 : code,
        command: commandStr,
        durationMs: Date.now() - start,
      });
    });
  });
}

async function runJavaJson(mainClass, args, options) {
  const res = await runJava(mainClass, args, options);
  if (res.code !== 0) {
    throw new Error(
      `${mainClass} exited with code ${res.code}\nstderr:\n${res.stderr}`
    );
  }
  try {
    return JSON.parse(res.stdout);
  } catch (err) {
    throw new Error(
      `${mainClass} did not return valid JSON: ${err.message}\nstdout:\n${res.stdout.slice(0, 2000)}`
    );
  }
}

async function verifyJava() {
  return new Promise((resolve) => {
    const child = spawn('java', ['-version']);
    let stderr = '';
    child.stderr.on('data', (d) => { stderr += d.toString(); });
    child.on('error', () => resolve({ ok: false, version: null, message: 'java not found on PATH' }));
    child.on('close', (code) => {
      if (code !== 0) {
        resolve({ ok: false, version: null, message: stderr.trim() || 'java -version failed' });
        return;
      }
      const m = stderr.match(/version "(\d+)(?:\.(\d+))?(?:\.(\d+))?/);
      const major = m ? parseInt(m[1], 10) : null;
      resolve({
        ok: major != null && major >= 21,
        version: stderr.split('\n')[0].trim(),
        message: major != null && major < 21
          ? `Java ${major} detected; Anserini requires Java 21+`
          : null,
      });
    });
  });
}

function verifyAnseriniJar() {
  try {
    const jar = resolveAnseriniJar();
    return { ok: true, jar };
  } catch (err) {
    return { ok: false, jar: null, message: err.message };
  }
}

// ---------- Registry / reproduce helpers ----------

async function listPrebuiltIndexes(type = 'inverted') {
  return runJavaJson('io.anserini.cli.PrebuiltIndexRegistry', ['--type', type, '--list']);
}

async function listTopics() {
  return runJavaJson('io.anserini.cli.TopicsRegistry', ['--list']);
}

async function listReproduceConfigs() {
  return runJavaJson('io.anserini.reproduce.ReproduceFromPrebuiltIndexes', ['--list']);
}

async function showReproduceConfig(name) {
  const res = await runJava('io.anserini.reproduce.ReproduceFromPrebuiltIndexes', [
    '--config', name, '--show',
  ]);
  if (res.code !== 0) {
    throw new Error(`Failed to show reproduce config ${name}: ${res.stderr}`);
  }
  return res.stdout;
}

// ---------- Retrieval / eval ----------

async function searchCollection({ index, topics, output, hits = 1000, threads = 1, bm25 = true }) {
  const args = [
    '-threads', String(threads),
    '-index', index,
    '-topics', topics,
    '-output', output,
    '-hits', String(hits),
  ];
  if (bm25) args.push('-bm25');
  return runJava('io.anserini.search.SearchCollection', args);
}

/**
 * Evaluate a TREC run using io.anserini.eval.TrecEval.
 *
 * @param {object} params
 * @param {string[]} params.metricArgs   The exact `-c -m ...` args from the
 *                                       reproduction config or user metric.
 * @param {string} params.qrels          The eval/qrels symbol (e.g. "cacm").
 * @param {string} params.runFile        Path to the TREC run file.
 */
async function trecEval({ metricArgs, qrels, runFile }) {
  const args = [...metricArgs, qrels, runFile];
  return runJava('io.anserini.eval.TrecEval', args);
}

module.exports = {
  resolveAnseriniJar,
  runJava,
  runJavaJson,
  verifyJava,
  verifyAnseriniJar,
  listPrebuiltIndexes,
  listTopics,
  listReproduceConfigs,
  showReproduceConfig,
  searchCollection,
  trecEval,
};

/**
 * Build a unified catalog of Anserini prebuilt Lucene inverted indexes,
 * pairing each with topic / qrels / metric information derived from the
 * shipped reproduction configs whenever such a pairing exists.
 *
 * Pairing logic:
 *   - Pull all inverted prebuilt indexes from PrebuiltIndexRegistry.
 *   - Pull all reproduce configs from ReproduceFromPrebuiltIndexes.
 *   - For each (condition, topic) pair, expand the `-index` flag in the
 *     condition's command template by substituting `$topics` with the
 *     topic_key and tagging the index with the resulting pairing.
 *
 * No pairings are hardcoded. CACM appears as evaluable only because the
 * shipped `cacm` reproduction config defines that pairing.
 */

const YAML = require('yaml');
const anserini = require('./anserini');

// Metrics that the app exposes on top of whatever the reproduction config
// already defines. These map a user-friendly label to the exact `-c -m ...`
// trec_eval args expected by io.anserini.eval.TrecEval. Every metric here is a
// real trec_eval metric and the args are taken from Anserini's own
// reproduction configs (see msmarco-v1-passage.core, beir.core, etc.).
const STANDARD_METRICS = [
  { label: 'nDCG@10', args: ['-c', '-m', 'ndcg_cut.10'] },
  { label: 'Recall@1000', args: ['-c', '-m', 'recall.1000'] },
  { label: 'MAP', args: ['-c', '-m', 'map'] },
  { label: 'P@30', args: ['-c', '-m', 'P.30'] },
];

function parseCommand(commandStr) {
  // Lightweight tokenizer that respects double-quoted args. The shipped
  // reproduce-config commands don't currently use shell quoting but this keeps
  // the parser robust to future additions.
  const tokens = [];
  let cur = '';
  let inQuotes = false;
  for (const ch of commandStr) {
    if (ch === '"') { inQuotes = !inQuotes; continue; }
    if (!inQuotes && /\s/.test(ch)) {
      if (cur) { tokens.push(cur); cur = ''; }
    } else {
      cur += ch;
    }
  }
  if (cur) tokens.push(cur);
  return tokens;
}

function extractFlag(tokens, flag) {
  const idx = tokens.indexOf(flag);
  if (idx === -1 || idx + 1 >= tokens.length) return null;
  return tokens[idx + 1];
}

function substitute(template, vars) {
  if (template == null) return template;
  // Replace $name and ${name} occurrences using a simple, ordered scan.
  return template.replace(/\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?/g, (m, name) =>
    Object.prototype.hasOwnProperty.call(vars, name) ? vars[name] : m
  );
}

function metricArgsFor(label, perPairingMap) {
  if (perPairingMap && perPairingMap[label]) {
    // Per-pairing definitions from the reproduce config are the ground truth.
    return perPairingMap[label].split(/\s+/).filter(Boolean);
  }
  const std = STANDARD_METRICS.find((m) => m.label === label);
  return std ? [...std.args] : null;
}

/**
 * Extract a list of pairings { indexName, topics, evalKey, metrics, condition, configName }
 * from a single reproduction config YAML string.
 */
function pairingsFromConfig(configName, yamlText) {
  const doc = YAML.parse(yamlText);
  const pairings = [];
  if (!doc || !Array.isArray(doc.conditions)) return pairings;
  for (const condition of doc.conditions) {
    if (!condition || !condition.command || !Array.isArray(condition.topics)) continue;
    const tokens = parseCommand(condition.command);
    const indexTpl = extractFlag(tokens, '-index');
    const topicsTpl = extractFlag(tokens, '-topics');
    if (!indexTpl || !topicsTpl) continue;
    for (const t of condition.topics) {
      if (!t || !t.topic_key || !t.eval_key) continue;
      const vars = { topics: t.topic_key, threads: '1' };
      const resolvedIndex = substitute(indexTpl, vars);
      const resolvedTopics = substitute(topicsTpl, vars);
      // Only keep pairings whose -index resolves to something concrete.
      if (resolvedIndex.includes('$')) continue;

      const perPairing = t.metric_definitions || {};
      const metrics = [];
      const seen = new Set();
      // Per-pairing metrics first (preferred when available).
      for (const [label, raw] of Object.entries(perPairing)) {
        metrics.push({
          label,
          args: raw.split(/\s+/).filter(Boolean),
          source: 'reproduce-config',
        });
        seen.add(label);
      }
      // Then add any standard metrics that aren't already listed.
      for (const std of STANDARD_METRICS) {
        if (!seen.has(std.label)) {
          metrics.push({ label: std.label, args: [...std.args], source: 'standard' });
        }
      }

      pairings.push({
        configName,
        conditionName: condition.name,
        conditionDisplay: condition.display || condition.name,
        indexName: resolvedIndex,
        topics: resolvedTopics,
        topicKey: t.topic_key,
        evalKey: t.eval_key,
        metrics,
        expectedScores: t.expected_scores || {},
      });
    }
  }
  return pairings;
}

/**
 * Group raw pairings by index name, keeping all conditions/topics that map to
 * each index. The CACM pairing ends up as one entry per condition; BEIR
 * indexes (e.g. beir-v1.0.0-trec-covid.flat) end up with one entry per topic.
 */
function groupPairingsByIndex(pairings) {
  const byIndex = new Map();
  for (const p of pairings) {
    if (!byIndex.has(p.indexName)) byIndex.set(p.indexName, []);
    byIndex.get(p.indexName).push(p);
  }
  return byIndex;
}

/**
 * Build the full catalog by combining the prebuilt-index registry with the
 * pairings extracted from the reproduce configs.
 *
 * @returns {Promise<{indexes: Array, pairings: Array, generatedAt: string,
 *                   anseriniJar: string, configCount: number, indexCount: number}>}
 */
async function buildCatalog() {
  const [indexes, configs] = await Promise.all([
    anserini.listPrebuiltIndexes('inverted'),
    anserini.listReproduceConfigs(),
  ]);

  const allPairings = [];
  for (const cfg of configs) {
    let text;
    try {
      text = await anserini.showReproduceConfig(cfg);
    } catch (err) {
      // Skip unreadable configs but keep the rest of the catalog usable.
      continue;
    }
    try {
      const pairings = pairingsFromConfig(cfg, text);
      allPairings.push(...pairings);
    } catch (err) {
      // Skip configs that don't follow the expected YAML shape.
      continue;
    }
  }

  const grouped = groupPairingsByIndex(allPairings);

  const enriched = indexes.map((idx) => {
    const indexPairings = grouped.get(idx.name) || [];
    return {
      name: idx.name,
      type: idx.type,
      description: idx.description || '',
      filename: idx.filename || null,
      size: idx.size || null,
      documents: idx.documents || null,
      uniqueTerms: idx.unique_terms || null,
      totalTerms: idx.total_terms || null,
      evaluable: indexPairings.length > 0,
      pairings: indexPairings,
    };
  });

  // Stable sort: evaluable first, CACM at the very top because the PRD makes it
  // the default end-to-end target.
  enriched.sort((a, b) => {
    if (a.name === 'cacm') return -1;
    if (b.name === 'cacm') return 1;
    if (a.evaluable !== b.evaluable) return a.evaluable ? -1 : 1;
    return a.name.localeCompare(b.name);
  });

  return {
    indexes: enriched,
    pairings: allPairings,
    generatedAt: new Date().toISOString(),
    anseriniJar: anserini.resolveAnseriniJar(),
    configCount: configs.length,
    indexCount: indexes.length,
  };
}

module.exports = {
  buildCatalog,
  pairingsFromConfig,
  parseCommand,
  substitute,
  STANDARD_METRICS,
  metricArgsFor,
};

/**
 * Anserini Prebuilt Index Evaluator — local web server.
 *
 * Endpoints:
 *   GET  /api/health             - check fatjar + Java availability
 *   GET  /api/catalog            - registry-derived index catalog (+ pairings)
 *   POST /api/evaluate           - run retrieval + evaluation for one pairing
 *   GET  /api/artifacts/:name    - serve a run or eval artifact for inspection
 *
 * All Anserini work is delegated to lib/anserini.js, which shells out to
 * `java -cp $ANSERINI_JAR ...`. No retrieval results, run files, evaluation
 * scores, or catalog entries are mocked or hardcoded.
 */

const express = require('express');
const fs = require('node:fs');
const path = require('node:path');
const anserini = require('./lib/anserini');
const catalog = require('./lib/catalog');

const PORT = parseInt(process.env.PORT || '4317', 10);
const ROOT = __dirname;
const ARTIFACTS_DIR = path.join(ROOT, 'artifacts');
fs.mkdirSync(ARTIFACTS_DIR, { recursive: true });

const app = express();
app.use(express.json({ limit: '1mb' }));
app.use(express.static(path.join(ROOT, 'public')));

// In-memory catalog cache (build is expensive: 17 JVM spawns ~ 1 min).
let catalogPromise = null;
function getCatalog(force = false) {
  if (force || !catalogPromise) {
    catalogPromise = catalog.buildCatalog().catch((err) => {
      catalogPromise = null;
      throw err;
    });
  }
  return catalogPromise;
}

// Warm up the catalog as soon as the server starts so the UI loads fast.
function warmCatalog() {
  getCatalog().catch((err) => {
    console.error('[catalog] warmup failed:', err.message);
  });
}

// ---------- Endpoints ----------

app.get('/api/health', async (_req, res) => {
  const javaCheck = await anserini.verifyJava();
  const jarCheck = anserini.verifyAnseriniJar();
  res.json({
    ok: javaCheck.ok && jarCheck.ok,
    java: javaCheck,
    anseriniJar: jarCheck,
  });
});

app.get('/api/catalog', async (_req, res) => {
  try {
    const data = await getCatalog();
    res.json(data);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/catalog/refresh', async (_req, res) => {
  try {
    const data = await getCatalog(true);
    res.json({ ok: true, generatedAt: data.generatedAt });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

/**
 * Body shape:
 *   {
 *     indexName: "cacm",
 *     topics:    "cacm",
 *     evalKey:   "cacm",
 *     metricLabel: "MAP",         // or "nDCG@10" / "Recall@1000" / ...
 *     metricArgs:  ["-c","-m","map"]  // optional; falls back to lookup
 *   }
 */
app.post('/api/evaluate', async (req, res) => {
  const start = Date.now();
  const { indexName, topics, evalKey, metricLabel } = req.body || {};
  let metricArgs = Array.isArray(req.body?.metricArgs) ? req.body.metricArgs : null;

  if (!indexName || !topics || !evalKey || !metricLabel) {
    res.status(400).json({
      error: 'indexName, topics, evalKey, and metricLabel are required',
    });
    return;
  }

  // Look up the pairing in the catalog so we can prefer the reproduction
  // config's per-pairing metric args when the client did not supply them.
  let resolvedPairing = null;
  try {
    const cat = await getCatalog();
    const idx = cat.indexes.find((i) => i.name === indexName);
    if (!idx) {
      res.status(400).json({ error: `Unknown index: ${indexName}` });
      return;
    }
    if (!idx.evaluable) {
      res.status(400).json({
        error: `Index ${indexName} is catalog-only: no topics/qrels pairing is registered for it.`,
      });
      return;
    }
    resolvedPairing = idx.pairings.find(
      (p) => p.topics === topics && p.evalKey === evalKey
    );
    if (!resolvedPairing) {
      res.status(400).json({
        error: `No registered pairing on ${indexName} for topics=${topics}, evalKey=${evalKey}`,
      });
      return;
    }
    if (!metricArgs) {
      const m = resolvedPairing.metrics.find((mm) => mm.label === metricLabel);
      if (!m) {
        res.status(400).json({
          error: `Metric "${metricLabel}" is not available for this pairing`,
        });
        return;
      }
      metricArgs = m.args;
    }
  } catch (err) {
    res.status(500).json({ error: `Catalog lookup failed: ${err.message}` });
    return;
  }

  // Build artifact paths. Names include a timestamp so repeated runs do not
  // clobber prior artifacts; the user can inspect them via /api/artifacts/:name.
  const safeIndex = indexName.replace(/[^A-Za-z0-9._-]/g, '_');
  const safeTopics = topics.replace(/[^A-Za-z0-9._-]/g, '_');
  const safeMetric = metricLabel.replace(/[^A-Za-z0-9._-]/g, '_');
  const stamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
  const runBase = `run.${safeIndex}.${safeTopics}.bm25.${stamp}.txt`;
  const evalBase = `eval.${safeIndex}.${safeTopics}.${safeMetric}.${stamp}.txt`;
  const runFile = path.join(ARTIFACTS_DIR, runBase);
  const evalFile = path.join(ARTIFACTS_DIR, evalBase);

  // ---- Retrieval ----
  let searchRes;
  try {
    searchRes = await anserini.searchCollection({
      index: indexName,
      topics,
      output: runFile,
      hits: 1000,
      threads: 1,
      bm25: true,
    });
  } catch (err) {
    res.status(500).json({
      error: `SearchCollection failed to launch: ${err.message}`,
      stage: 'retrieval',
    });
    return;
  }
  if (searchRes.code !== 0 || !fs.existsSync(runFile)) {
    res.status(500).json({
      error: 'SearchCollection did not produce a run file',
      stage: 'retrieval',
      command: searchRes.command,
      exitCode: searchRes.code,
      stderr: tail(searchRes.stderr, 4000),
    });
    return;
  }

  // ---- Evaluation ----
  let evalRes;
  try {
    evalRes = await anserini.trecEval({
      metricArgs,
      qrels: evalKey,
      runFile,
    });
  } catch (err) {
    res.status(500).json({
      error: `TrecEval failed to launch: ${err.message}`,
      stage: 'evaluation',
    });
    return;
  }
  if (evalRes.code !== 0) {
    res.status(500).json({
      error: 'TrecEval exited with a non-zero status',
      stage: 'evaluation',
      command: evalRes.command,
      exitCode: evalRes.code,
      stderr: tail(evalRes.stderr, 4000),
      stdout: tail(evalRes.stdout, 4000),
    });
    return;
  }

  fs.writeFileSync(evalFile, evalRes.stdout);

  const parsed = parseTrecEvalOutput(evalRes.stdout);
  // Match the user-visible metric label to a row in the trec_eval output.
  const primary = pickPrimaryScore(parsed, metricLabel, metricArgs);

  res.json({
    ok: true,
    indexName,
    topics,
    evalKey,
    metric: { label: metricLabel, args: metricArgs },
    score: primary ? primary.score : null,
    scoreRow: primary ? primary.row : null,
    allScores: parsed,
    expectedScores: resolvedPairing.expectedScores,
    runFile: path.relative(ROOT, runFile),
    runArtifact: runBase,
    runPreview: tail(fs.readFileSync(runFile, 'utf8'), 4000),
    evalFile: path.relative(ROOT, evalFile),
    evalArtifact: evalBase,
    evalOutput: evalRes.stdout,
    retrievalCommand: searchRes.command,
    evaluationCommand: evalRes.command,
    retrievalMs: searchRes.durationMs,
    evaluationMs: evalRes.durationMs,
    totalMs: Date.now() - start,
  });
});

app.get('/api/artifacts/:name', (req, res) => {
  const name = req.params.name;
  if (!/^[A-Za-z0-9._-]+$/.test(name)) {
    res.status(400).send('Invalid artifact name');
    return;
  }
  const file = path.join(ARTIFACTS_DIR, name);
  if (!fs.existsSync(file)) {
    res.status(404).send('Artifact not found');
    return;
  }
  res.type('text/plain').send(fs.readFileSync(file));
});

// ---------- Helpers ----------

function tail(text, max) {
  if (!text) return '';
  return text.length > max ? text.slice(text.length - max) : text;
}

/**
 * Parse `trec_eval` style output. Each line looks like:
 *   "map                   \tall\t0.3123"
 * Returns rows for the "all" aggregate only, which is what the UI surfaces.
 */
function parseTrecEvalOutput(stdout) {
  const rows = [];
  for (const line of stdout.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const parts = trimmed.split(/\s+/);
    if (parts.length < 3) continue;
    const [metric, qid, value] = parts;
    if (qid !== 'all') continue;
    const score = Number(value);
    if (Number.isNaN(score)) continue;
    rows.push({ metric, qid, score });
  }
  return rows;
}

/**
 * Translate a user-visible metric label (and its TrecEval args) into the
 * matching row in the parsed output.
 */
function pickPrimaryScore(rows, label, args) {
  if (rows.length === 0) return null;

  // The actual metric name appears as the last `-m <name>` argument.
  let mFlag = null;
  for (let i = 0; i < args.length - 1; i++) {
    if (args[i] === '-m') mFlag = args[i + 1];
  }
  if (mFlag) {
    // Convert e.g. "ndcg_cut.10" -> "ndcg_cut_10" because trec_eval normalises
    // dots to underscores in its output column.
    const normalised = mFlag.replace(/\./g, '_');
    const match = rows.find(
      (r) => r.metric === normalised || r.metric === mFlag
    );
    if (match) return { row: match, score: match.score };
  }

  // Fall back to label-based fuzzy match (covers MAP vs map, P@30 vs P_30).
  const fuzz = label.toLowerCase().replace(/[^a-z0-9]/g, '');
  const match = rows.find(
    (r) => r.metric.toLowerCase().replace(/[^a-z0-9]/g, '') === fuzz
  );
  if (match) return { row: match, score: match.score };

  return { row: rows[0], score: rows[0].score };
}

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Anserini evaluator listening on http://localhost:${PORT}`);
    warmCatalog();
  });
  process.on('SIGTERM', () => server.close());
  process.on('SIGINT', () => { server.close(); process.exit(0); });
}

module.exports = { app, getCatalog };

